# Adding Rooms

Enhance the connection manager to support rooms. Each room has its own list of connections.

```python
class RoomManager:
    def __init__(self):
        self.rooms: dict[str, list[WebSocket]] = {}

    async def connect(self, room: str, websocket: WebSocket):
        await websocket.accept()
        if room not in self.rooms:
            self.rooms[room] = []
        self.rooms[room].append(websocket)

    def disconnect(self, room: str, websocket: WebSocket):
        self.rooms[room].remove(websocket)
        if not self.rooms[room]:
            del self.rooms[room]
```

```python
manager = RoomManager()

@app.websocket("/chat/{room_name}")
async def chat_room(websocket: WebSocket, room_name: str):
    await manager.connect(room_name, websocket)
    try:
        while True:
            data = await websocket.receive_text()
            # Broadcast to everyone in the same room
            for conn in manager.rooms[room_name]:
                if conn != websocket:  # don't echo to sender
                    await conn.send_text(data)
    except WebSocketDisconnect:
        manager.disconnect(room_name, websocket)
        # Optionally notify others
