from fastapi import FastAPI, WebSocket, WebSocketDisconnect
from typing import Dict, List

app = FastAPI()

class RoomManager:
    def __init__(self):
        self.rooms: Dict[str, List[WebSocket]] = {}

    async def connect(self, room: str, websocket: WebSocket):
        await websocket.accept()
        if room not in self.rooms:
            self.rooms[room] = []
        self.rooms[room].append(websocket)

    def disconnect(self, room: str, websocket: WebSocket):
        self.rooms[room].remove(websocket)
        if not self.rooms[room]:
            del self.rooms[room]

    async def broadcast(self, room: str, message: str, exclude: WebSocket = None):
        for conn in self.rooms.get(room, []):
            if conn != exclude:
                await conn.send_text(message)

manager = RoomManager()

@app.websocket("/ws/{room}")
async def websocket_room(websocket: WebSocket, room: str):
    await manager.connect(room, websocket)
    try:
        while True:
            msg = await websocket.receive_text()
            await manager.broadcast(room, msg, exclude=websocket)
    except WebSocketDisconnect:
        manager.disconnect(room, websocket)
        await manager.broadcast(room, "A user left", exclude=websocket)
